INSERT INTO public.sectors (id, number, title, subtitle, summary, full_description, accent_color, badge_text, scope, beneficiaries, tags, sla_highlight)
VALUES
    ('contracting', '01', 'المقاولات والتطوير الإنشائي', 'تشييد وتأهيل عمراني وفق أعلى المعايير الهندسية السعودية', 'تنفيذ المشاريع الإنشائية، التطوير العمراني، التأهيل المعماري، وأعمال التشطيبات الفاخرة.', 'يتولى قطاع المقاولات والتطوير الإنشائي في رواسي العمر تنفيذ وتهيئة المقرات المؤسسية والمباني الوقفية والمراكز المجتمعية بنموذج تسليم المفتاح.', '#163063', 'تنفيذ هندسي معتمد', ARRAY['الأعمال الإنشائية والهيكلية المتكاملة', 'إعادة التأهيل المعماري والترميم', 'أعمال التشطيبات الفاخرة', 'أنظمة الكهروميكانيك MEP والسلامة'], ARRAY['الجمعيات الأهلية والمؤسسات الخيرية', 'الأوقاف والنظار المطورون للأصول', 'الشركات والمطورون العقاريون'], ARRAY['إنشاءات متقدمة', 'تشطيبات معمارية', 'تسليم مفتاح'], 'التزام صارم بالجدول الزمني والمواصفات الفنية المعتمدة بنسبة 100%'),
    ('supply', '02', 'التجهيز والتوريد المتكامل', 'تأثيث وتجهيز المقرات والمراكز وفق معايير الكفاءة الوظيفية', 'تأثيث المقرات الإدارية والتعليمية والفندقية وتوريد التجهيزات الميدانية.', 'نوفر حلول التجهيز والتوريد الشاملة التي تحول المساحات إلى بيئات عمل واستقبال جاهزة للتشغيل الفوري.', '#2360A5', 'إمداد وتجهيز شامل', ARRAY['توريد وتركيب الأثاث المكتبي التنفيذي', 'تجهيز قاعات الاجتماعات والجمعيات العمومية', 'التجهيزات الصوتية والمرئية التفاعلية'], ARRAY['المقرات الإدارية للجمعيات', 'المراكز التعليمية والتدريبية', 'المباني الاستثمارية والضيافية'], ARRAY['تأثيث مقرات', 'تجهيز مكتبي شامل', 'سلاسل إمداد'], 'توريد موحد من مصدر مسؤول واحد دون تشتت بين عشرات الموردين'),
    ('tech', '03', 'التقنية والحلول الذكية', 'بنية رقمية متكاملة ومنصات مؤسسية متوافقة مع التحول الوطني', 'بناء البنى التحتية الرقمية، المنصات السحابية، وربط أنظمة ERP.', 'يمكّن قطاع التقنية الجهات غير الربحية والشركات من الانتقال لمنظومات رقمية مؤتمتة آمنة.', '#3488C4', 'تحول رقمي وحلول ذكية', ARRAY['تأسيس البنية التحتية للشبكات والسيرفرات', 'تطبيق أنظمة تخطيط الموارد ERP والحوكمة', 'تطوير البوابات الرقمية ومتاجر التبرع'], ARRAY['الجمعيات الساعية لرفع الحوكمة التقنية', 'المؤسسات الوقفية متعددة الأصول', 'الشركات المتوسطة والنامية'], ARRAY['منصات سحابية', 'تحول رقمي', 'أنظمة ERP'], 'امتثال رقمي كامل لمتطلبات الحوكمة وأمن البيانات السعودية'),
    ('operations', '04', 'التشغيل والصيانة المستدامة', 'حماية القيمة السوقية واستدامة الكفاءة التشغيلية للمرافق', 'إدارة شاملة للمرافق الحيوية وبرامج صيانة وقائية وطارئة.', 'برامج منهجية لإدارة المرافق والصيانة الوقائية لحماية القيمة السوقية للأصول.', '#2360A5', 'استدامة الأصول والمرافق', ARRAY['عقود التشغيل والصيانة الوقائية (FM)', 'إدارة أنظمة التكييف والكهرباء والمصاعد', 'برامج ترشيد استهلاك الطاقة'], ARRAY['الأوقاف العقارية والمجمعات الاستثمارية', 'المقرات الكبرى للجمعيات الأهلية', 'المجمعات التجارية والإدارية'], ARRAY['إدارة مرافق', 'صيانة وقائية', 'كفاءة تشغيلية'], 'تقليل الأعطال المفاجئة وإطالة العمر التشغيلي للأصل بكفاءة عالية'),
    ('community', '05', 'المشاريع والمبادرات المجتمعية', 'تصميم وتنفيذ مبادرات تنموية ذات أثر موثق وعائد اجتماعي', 'تصميم المبادرات التنموية وبرامج المسؤولية المجتمعية وقياس SROI.', 'تصميم وإدارة المبادرات وبرامج المسؤولية الاجتماعية (CSR) بمنهجية قياس كمية ونوعية.', '#47A3B8', 'أثر تنموي مستدام', ARRAY['تصميم المبادرات التنموية والتمكين', 'تشغيل الحملات المجتمعية والموسمية', 'بناء برامج المسؤولية الاجتماعية CSR', 'قياس العائد الاجتماعي على الاستثمار SROI'], ARRAY['الجمعيات الأهلية التخصصية', 'الصناديق المانحة والأوقاف', 'الشركات الكبرى في برامج CSR'], ARRAY['استدامة الأثر', 'قياس SROI', 'مسؤولية اجتماعية'], 'تحويل الإنفاق الخيري إلى أثر تنموي موثق وقابل للقياس')
